counts = [14, 12, 15, 13, 12, 18, 12, 16, 12, 13, 20, 12]
hrs = 730*12
od_rate = 0.1
ri_rate = 0.062

def total(k):
    # k RIs cover min(k, n) instances each month; rest on-demand
    cost = k*ri_rate*hrs
    for n in counts:
        if n > k:
            cost += (n-k)*od_rate*730
    return cost

for k in range(0, 25):
    print(k, round(total(k),2))

